import psutil

def check_parent_anomaly(proc_name, suspicious_parents):
    for proc in psutil.process_iter(['name', 'ppid']):
        if proc.info['name'] == proc_name:
            parent = psutil.Process(proc.info['ppid'])
            # If cmd.exe is spawned by 'httpd' or 'nginx', it's an anomaly
            if parent.name() in suspicious_parents:
                print(f"[!] Suspicious Parent: {parent.name()} spawned {proc_name}")

# Check for shells spawned by web servers
check_parent_anomaly("cmd.exe", ["httpd.exe", "nginx.exe", "w3wp.exe"])

