def analyze_report(report_json):
    malicious_ips = ["1.2.3.4", "8.8.4.4"] # Example blacklist
    network_activity = report_json.get("network", {})

    for conn in network_activity.get("udp", []):
        dest_ip = conn.get("dst")
        if dest_ip in malicious_ips:
            print(f"[!] CRITICAL: Malware contacted blacklisted IP: {dest_ip}")
            return True
    return False

# Example report snippet
report = {"network": {"udp": [{"dst": "1.2.3.4", "port": 53}]}}
analyze_report(report)
